/** Independent geometry reader. Derives buses and source/target contacts from
 * actual polyline coordinates, rect/ellipse and filled marker, not role attrs. */
import assert from'node:assert/strict';import facts from'./legacy-2018-pm-cloud-facts.json';
type Point=[number,number];type Segment=[Point,Point];
const attrs=(s:string)=>Object.fromEntries([...s.matchAll(/([\w:-]+)="([^"]*)"/g)].map(m=>[m[1],m[2]]));
const nums=(s:string)=>s.split(/[ ,]+/).filter(Boolean).map(Number);const text=(s:string)=>s.replace(/<[^>]*>/g,'').replaceAll('&amp;','&');
const boxes=[['client',60,20,170,36,'クライアント'],['loadFront',210,180,160,40,'負荷分散装置'],['loadReplica',730,180,160,40,'負荷分散装置'],...[[50,'f0'],[200,'f1'],[350,'f2']].map(([x,id])=>[id,x,290,120,72,'フロントサーバ']),...[[600,'r0'],[750,'r1'],[900,'r2']].map(([x,id])=>[id,x,290,120,72,'レプリケーションサーバ']),['db',80,450,140,40,'DBサーバ'],['queue',280,450,160,40,'キューサーバ'],['storage',550,450,220,40,'ストレージサーバ'],...[[50,'b0'],[200,'b1'],[350,'b2']].map(([x,id])=>[id,x,580,120,72,'バックサーバ'])]as (string|number)[][];
const expectedRoles=['client>internet','internet>loadFront','internet>loadReplica','loadFront>front','loadReplica>replica','front>db','front>queue','front>storage','back>db','back>queue','back>storage','replica>storage'].sort();
const pointEq=(a:Point,b:Point)=>Math.hypot(a[0]-b[0],a[1]-b[1])<.01;
function onSegment(p:Point,[a,b]:Segment){return Math.abs((p[0]-a[0])*(b[1]-a[1])-(p[1]-a[1])*(b[0]-a[0]))<.01&&p[0]>=Math.min(a[0],b[0])-.01&&p[0]<=Math.max(a[0],b[0])+.01&&p[1]>=Math.min(a[1],b[1])-.01&&p[1]<=Math.max(a[1],b[1])+.01;}
function touch(a:Segment,b:Segment){if(a.some(p=>onSegment(p,b))||b.some(p=>onSegment(p,a)))return true;const vertical=a[0][0]===a[1][0]?a:b,horizontal=vertical===a?b:a;if(vertical[0][0]!==vertical[1][0]||horizontal[0][1]!==horizontal[1][1])return false;return onSegment([vertical[0][0],horizontal[0][1]],a)&&onSegment([vertical[0][0],horizontal[0][1]],b);}
export function readLegacy2018CloudSvg(svg:string){assert(svg.includes('viewBox="0 0 1050 710"'));assert.equal(text(svg.match(/<desc[^>]*>([\s\S]*?)<\/desc>/)![1]),facts.figureAlt);
 const groups=[...svg.matchAll(/<g data-cloud-node="[^"]*">([\s\S]*?)<\/g>/g)];assert.equal(groups.length,16);const nodes:Record<string,{shape:'box';x:number;y:number;w:number;h:number}|{shape:'ellipse';x:number;y:number;rx:number;ry:number}>={};
 for(const m of groups){const label=text(m[1].match(/<text[^>]*>([\s\S]*?)<\/text>/)![1]),ta=attrs(m[1].match(/<text([^>]*)>/)![1]);if(m[1].includes('<ellipse')){const a=attrs(m[1].match(/<ellipse([^>]*)>/)![1]);assert.equal(label,'インターネット');assert.deepEqual([+a.cx,+a.cy,+a.rx,+a.ry],[525,100,470,30]);assert.deepEqual([+ta.x,+ta.y],[525,100]);nodes.internet={shape:'ellipse',x:+a.cx,y:+a.cy,rx:+a.rx,ry:+a.ry};continue;}
 const a=attrs(m[1].match(/<rect([^>]*)>/)![1]),row=boxes.find(n=>+n[1]===+a.x&&+n[2]===+a.y);assert(row,'source position changed');assert.equal(label,row[5]);assert.deepEqual([+a.width,+a.height],[+row[3],+row[4]]);assert.equal(+ta.x,+a.x+ +a.width/2);assert.equal(+ta.y,+a.y+ +a.height/2-(m[1].match(/<tspan/g)!.length-1)*12);const tspans=[...m[1].matchAll(/<tspan([^>]*)>/g)].map(n=>attrs(n[1]));for(const t of tspans)assert.equal(+t.x,+ta.x);assert(tspans.every((t,i)=>+t.dy===(i?24:0)));nodes[String(row[0])]={shape:'box',x:+a.x,y:+a.y,w:+a.width,h:+a.height};}
 assert.equal(Object.keys(nodes).length,16);const pointNode=(p:Point)=>Object.entries(nodes).filter(([,n])=>n.shape==='box'?(((Math.abs(p[0]-n.x)<.01||Math.abs(p[0]-n.x-n.w)<.01)&&p[1]>=n.y&&p[1]<=n.y+n.h)||((Math.abs(p[1]-n.y)<.01||Math.abs(p[1]-n.y-n.h)<.01)&&p[0]>=n.x&&p[0]<=n.x+n.w)):Math.abs(((p[0]-n.x)/n.rx)**2+((p[1]-n.y)/n.ry)**2-1)<.005).map(([id])=>id);
 const markers=[...svg.matchAll(/<marker([^>]*)>([\s\S]*?)<\/marker>/g)];assert.equal(markers.length,1);const ma=attrs(markers[0][1]),mp=attrs(markers[0][2].match(/<path([^>]*)>/)![1]);assert.deepEqual([ma.viewBox,ma.refX,ma.refY,ma.orient],['0 0 12 12','10','6','auto']);assert.equal(mp.d,'M 1 1 L 10 6 L 1 11 Z');assert.equal(mp.fill,'currentColor');assert.equal(mp.stroke,'currentColor');
 const paths=[...svg.matchAll(/<polyline([^>]*)>/g)].map(m=>{const a=attrs(m[1]),n=nums(a.points);assert(n.length>=4&&n.length%2===0);const points:Array<Point>=[];for(let i=0;i<n.length;i+=2)points.push([n[i],n[i+1]]);assert.equal(a.fill,'none');if(a['marker-end'])assert.equal(a['marker-end'],`url(#${ma.id})`);return{points,arrow:!!a['marker-end']};});assert.equal(paths.length,26);assert.equal(paths.filter(p=>p.arrow).length,16);
 const segments=paths.flatMap((p,i)=>p.points.slice(1).map((b,j)=>({path:i,s:[p.points[j],b]as Segment})));assert(segments.every(e=>e.s[0][0]===e.s[1][0]||e.s[0][1]===e.s[1][1]));
 const parent=segments.map((_,i)=>i),find=(n:number):number=>parent[n]===n?n:parent[n]=find(parent[n]);for(let i=0;i<segments.length;i++)for(let j=0;j<i;j++)if(touch(segments[i].s,segments[j].s))parent[find(i)]=find(j);
 const components=new Map<number,number[]>();for(let i=0;i<segments.length;i++){const id=find(i);components.set(id,[...(components.get(id)??[]),i]);}
 const relations:string[]=[];for(const members of components.values()){const pathIds=[...new Set(members.map(i=>segments[i].path))],targets=pathIds.filter(i=>paths[i].arrow).flatMap(i=>{const ids=pointNode(paths[i].points.at(-1)!);assert.equal(ids.length,1,'arrow must terminate at an actual node boundary');return ids;}),contacts=[...new Set(members.flatMap(i=>segments[i].s.flatMap(pointNode)))],sources=contacts.filter(n=>!targets.includes(n));assert(sources.length&&targets.length,'direction or disconnected bus');for(const source of sources)for(const target of targets)relations.push(source+'>'+target);}
 const role=(n:string)=>/^[frb][0-2]$/.test(n)?({f:'front',r:'replica',b:'back'}[n[0]as'f'|'r'|'b']):n;const roles=[...new Set(relations.map(e=>e.split('>').map(role).join('>')))].sort();assert.deepEqual(roles,expectedRoles);assert.equal(relations.length,30);
 const ellipses=[...svg.matchAll(/<text([^>]*)data-cloud-ellipsis="pool"([^>]*)>(.*?)<\/text>/g)];assert.equal(ellipses.length,3);assert(ellipses.every(m=>m[3]==='…'));assert(svg.includes('DB：データベース'));assert(!/グループ|15672|15432/.test(svg));return{nodes:16,roleEdges:roles,instanceEdges:relations.length,arrows:16,pools:3};
}
